// src/v1.ts
import * as path3 from "node:path";
import { xdgData } from "xdg-basedir";

// src/imagegen.ts
import { z } from "zod";

// src/size.ts
var IMAGE_SIZES = {
  "1254x1254": "1:1",
  "1536x1024": "3:2",
  "1024x1536": "2:3",
  "1448x1086": "4:3",
  "1086x1448": "3:4",
  "1672x941": "16:9",
  "941x1672": "9:16"
};
var SIZE_CHOICES = Object.entries(IMAGE_SIZES).map(([size, aspectRatio]) => `${size} (${aspectRatio})`).join(", ");
function appendSizeToPrompt(prompt, size) {
  const [width, height] = size.split("x");
  return `${prompt} Generate the image with a width of ${width} pixels and a height of ${height} pixels (${IMAGE_SIZES[size]} aspect ratio).`;
}

// src/codex.ts
var CODEX_IMAGES_BASE_URL = "https://chatgpt.com/backend-api/codex";
var CODEX_REQUEST_DEFAULTS = { model: "gpt-image-2", quality: "auto", size: "auto" };
async function resolveImagesTarget(connection, loadOpenAIAuth) {
  if (connection.baseURL) {
    return { baseURL: connection.baseURL, headers: {} };
  }
  const auth = await loadOpenAIAuth();
  if (!auth) {
    throw new Error("OpenAI ChatGPT OAuth credentials not configured.");
  }
  return {
    baseURL: CODEX_IMAGES_BASE_URL,
    headers: {
      Authorization: `Bearer ${auth.access}`,
      ...auth.accountId ? { "ChatGPT-Account-Id": auth.accountId } : {}
    }
  };
}
function imagesEndpoint(baseURL, operation) {
  return new URL(`images/${operation}`, baseURL.endsWith("/") ? baseURL : `${baseURL}/`).toString();
}
async function requestCodexImage(connection, loadOpenAIAuth, request, signal) {
  const target = await resolveImagesTarget(connection, loadOpenAIAuth);
  const isEdit = request.images.length > 0;
  const body = {
    prompt: appendSizeToPrompt(request.prompt, request.size),
    ...CODEX_REQUEST_DEFAULTS,
    background: request.background,
    ...isEdit ? { images: request.images.map((dataUrl) => ({ image_url: dataUrl })) } : {}
  };
  const res = await fetch(imagesEndpoint(target.baseURL, isEdit ? "edits" : "generations"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...target.headers,
      originator: "opencode"
    },
    body: JSON.stringify(body),
    signal
  });
  if (!res.ok) {
    const detail = await res.text().catch(() => "");
    throw new Error(`codex images request failed: ${res.status} ${detail.slice(0, 500)}`);
  }
  const image = (await res.json()).data?.[0]?.b64_json;
  if (!image) {
    throw new Error("no image returned by codex images endpoint");
  }
  return image;
}

// src/input-image.ts
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { fileTypeFromBuffer } from "file-type";
async function readImageAsDataUrl(filePath, ctxDir) {
  const abs = path.isAbsolute(filePath) ? filePath : path.resolve(ctxDir, filePath);
  const buf = await fs.readFile(abs);
  const detected = await fileTypeFromBuffer(buf);
  if (!detected?.mime.startsWith("image/")) {
    throw new Error(`unsupported image file type: ${abs}`);
  }
  return `data:${detected.mime};base64,${buf.toString("base64")}`;
}
async function readReferenceImages(paths, ctxDir) {
  return Promise.all((paths ?? []).map((p) => readImageAsDataUrl(p, ctxDir)));
}

// src/output-image.ts
import * as fs2 from "node:fs/promises";
import * as path2 from "node:path";
var MAX_OUTPUT_VERSION_SUFFIX = 999;
async function pathExists(p) {
  try {
    await fs2.access(p);
    return true;
  } catch {
    return false;
  }
}
async function pickNonOverwritePath(requested, maxVersion = MAX_OUTPUT_VERSION_SUFFIX) {
  if (!await pathExists(requested))
    return requested;
  const dir = path2.dirname(requested);
  const ext = path2.extname(requested);
  const stem = path2.basename(requested, ext);
  for (let n = 2;n <= maxVersion; n++) {
    const candidate = path2.join(dir, `${stem}-v${n}${ext}`);
    if (!await pathExists(candidate))
      return candidate;
  }
  throw new Error(`could not find a non-conflicting filename under ${dir}/${stem}-vN${ext} (tried up to v${maxVersion})`);
}
function readPngSize(png) {
  return { width: png.readUInt32BE(16), height: png.readUInt32BE(20) };
}
function buildSavedMessage(savedPath, requestedPath, size) {
  const versionNote = savedPath !== requestedPath ? ` (the requested path ${requestedPath} already existed; the new image was versioned to avoid overwriting it)` : "";
  return `Generated image saved to ${savedPath}${versionNote}. The image is ${size.width}x${size.height} pixels.`;
}
async function isDirectory(p) {
  try {
    return (await fs2.stat(p)).isDirectory();
  } catch {
    return false;
  }
}
async function ensureDir(dir) {
  try {
    await fs2.mkdir(dir, { recursive: true });
  } catch (e) {
    if (e.code !== "EEXIST" || !await isDirectory(dir))
      throw e;
  }
}
async function saveGeneratedImage(out, ctxDir, base64) {
  const requestedPath = path2.isAbsolute(out) ? out : path2.resolve(ctxDir, out);
  await ensureDir(path2.dirname(requestedPath));
  const savedPath = await pickNonOverwritePath(requestedPath);
  const png = Buffer.from(base64, "base64");
  await fs2.writeFile(savedPath, png);
  return {
    savedPath,
    versioned: savedPath !== requestedPath,
    message: buildSavedMessage(savedPath, requestedPath, readPngSize(png))
  };
}

// src/imagegen.ts
var argsShape = {
  prompt: z.string().describe("Description of the image to generate."),
  out: z.string().describe("Output file path, relative to the project directory unless absolute. The plugin writes a PNG."),
  size: z.enum(Object.keys(IMAGE_SIZES), {
    error: (issue) => issue.input == null ? `Missing size. Use one of: ${SIZE_CHOICES}.` : `Unsupported size "${issue.input}". Use one of: ${SIZE_CHOICES}.`
  }).describe([
    `Output size. Only these sizes can be generated: ${SIZE_CHOICES}.`,
    "Typical choices: 1672x941 for a 16:9 video thumbnail, 1254x1254 for a square icon, 941x1672 for a phone wallpaper."
  ].join(" ")),
  images: z.array(z.string()).max(5).nullish().describe("Optional reference image paths, up to 5, relative to the project directory unless absolute."),
  background: z.enum(["opaque", "transparent"]).nullish().describe([
    "Optional background of the output image. Defaults to `opaque`.",
    "Use `transparent` when the request calls for a transparent background, including background removal or a cutout.",
    "When editing reference images, preserve their existing transparency unless the user asks to change it."
  ].join(" "))
};
var argsSchema = z.object(argsShape);
var optionsSchema = z.object({
  baseURL: z.url({ protocol: /^https?$/ }).refine((value) => {
    const url = new URL(value);
    return url.search === "" && url.hash === "";
  }, "baseURL must not have a query or a fragment").optional()
});
function parseOptions(options) {
  const parsed = optionsSchema.safeParse(options ?? {});
  if (!parsed.success) {
    throw new Error(`invalid opencode-gpt-imagegen options: ${z.prettifyError(parsed.error)}`);
  }
  return parsed.data;
}
function createImagegenTool(options, loadOpenAIAuth) {
  const authNote = options?.baseURL ? "Sends requests to the proxy set by the plugin's `baseURL` option instead of ChatGPT, so ChatGPT OAuth is not used." : "Requires OpenCode to be authenticated with ChatGPT OAuth.";
  return {
    description: [
      "Generate raster images through the image generation endpoints of the ChatGPT Codex backend.",
      "Use for AI-created bitmap visuals such as photos, illustrations, textures, sprites, and mockups.",
      "Do not use when the task is better handled by editing existing SVG/vector/code-native assets, extending an established icon or logo system, or building the visual directly in HTML/CSS/canvas.",
      "Reference images may be attached through `images`; label each image's role inline in `prompt`, for example: 'Image 1: reference image'.",
      "For many distinct assets, invoke gpt_imagegen once per requested asset rather than relying on multi-image output; gpt_imagegen returns one image per call.",
      `${authNote} Returns the absolute path of the saved PNG.`,
      "Before generating, decide the size. If the user named a size that is not supported, or gave no size and the use does not clearly imply a shape, ask the user which size to use (with the question tool when available).",
      "In that question, offer every supported size as an option labeled like `1672x941 (16:9)`, put the one you recommend first with ` (Recommended)` appended to its label, and give each option a short description of what it suits.",
      "Do not add catch-all options such as 'Other' or 'Let me decide'.",
      "In the question text, say that other sizes cannot be generated directly and that the image can be resized or cropped to an exact size afterwards, for example with ImageMagick.",
      "If the use clearly implies a shape, such as a YouTube thumbnail or an app icon, pick the matching size without asking.",
      "The saved image can differ from the requested size by 1px, so do not promise exact pixel dimensions before generating. After generating, tell the user the size reported in the tool result."
    ].join(" "),
    schema: argsSchema,
    async execute(input, directory, signal) {
      const parsed = argsSchema.safeParse(input);
      if (!parsed.success) {
        throw new Error(z.prettifyError(parsed.error));
      }
      const args = parsed.data;
      const connection = parseOptions(options);
      const images = await readReferenceImages(args.images, directory);
      const base64 = await requestCodexImage(connection, loadOpenAIAuth, { prompt: args.prompt, size: args.size, background: args.background ?? "opaque", images }, signal);
      return saveGeneratedImage(args.out, directory, base64);
    }
  };
}

// src/v1-auth.ts
import * as fs3 from "node:fs/promises";
async function loadAuthData(envContent, authFile) {
  if (envContent) {
    return JSON.parse(envContent);
  }
  if (!authFile) {
    throw new Error("could not determine XDG data directory");
  }
  const raw = await fs3.readFile(authFile, "utf-8");
  return JSON.parse(raw);
}
async function loadOpenAIAuth(envContent, authFile) {
  try {
    const data = await loadAuthData(envContent, authFile);
    const entry = data.openai;
    if (entry?.type === "oauth" && typeof entry.access === "string") {
      return entry;
    }
  } catch {
    return;
  }
  return;
}

// src/v1.ts
var server = async (_input, options) => {
  const imagegen = createImagegenTool(options, () => loadOpenAIAuth(process.env.OPENCODE_AUTH_CONTENT, xdgData ? path3.join(xdgData, "opencode", "auth.json") : undefined));
  return {
    tool: {
      gpt_imagegen: {
        description: imagegen.description,
        args: imagegen.schema.shape,
        async execute(input, context) {
          const result = await imagegen.execute(input, context.directory, context.abort);
          return {
            output: result.message,
            metadata: { out: result.savedPath, versioned: result.versioned }
          };
        }
      }
    }
  };
};

// src/v2.ts
import { z as z2 } from "zod";

// src/v2-auth.ts
async function loadOpenAIAuth2(connections) {
  const connection = await connections.active("openai");
  const credential = connection ? await connections.resolve(connection) : undefined;
  if (!credential)
    return;
  if (credential.type !== "oauth" || credential.methodID !== "chatgpt-browser" && credential.methodID !== "chatgpt-headless") {
    const method = credential.type === "oauth" ? credential.methodID : credential.type;
    throw new Error(`The OpenAI connection's sign-in method (${method}) cannot generate images. In OpenCode, connect OpenAI and choose "Codex browser (legacy)" or "Codex device code (legacy)".`);
  }
  const accountId = credential.metadata?.accountID;
  return {
    type: "oauth",
    access: credential.access,
    ...typeof accountId === "string" ? { accountId } : {}
  };
}

// src/v2.ts
var setup = async (context) => {
  const imagegen = createImagegenTool(context.options, () => loadOpenAIAuth2(context.integration.connection));
  const input = z2.toJSONSchema(imagegen.schema, { io: "input" });
  await context.tool.transform((editor) => {
    editor.add({
      name: "gpt_imagegen",
      description: imagegen.description,
      input,
      options: { codemode: false },
      async execute(args, execution) {
        const session = await context.session.get({ sessionID: execution.sessionID });
        const result = await imagegen.execute(args, session.location.directory, execution.signal);
        return {
          content: result.message,
          metadata: { out: result.savedPath, versioned: result.versioned }
        };
      }
    });
  });
};

// src/index.ts
var src_default = {
  id: "opencode-gpt-imagegen",
  server,
  setup
};
export {
  src_default as default
};
